class _MinLengthValidator(Validator):
    def __init__(self, min_length):
        self.min_length = min_length

    def __call__(self, instance, defined, value):
        if len(value) < self.min_length:
            raise ValueError(
                "Length of '{name}' must be >= {min}: {len}".format(
                    name=defined.name, min=self.min_length, len=len(value)
                )
            )

    def __repr__(self):
        return "<min_len validator for {min}>".format(min=self.min_length)


